export function evaluate({inputs,time}){
const u=inputs.launchSpeed,g=inputs.gravity;
const ta=u/g,H=u*u/(2*g);
const t=Math.min(time,2*ta);
const y=u*t-g*t*t/2;
const tv=u-g*t;
const rel=t>=ta;
const dy=rel?y:H;
const dv=rel?-g*(t-ta):0;
const da=rel?-g:0;
const base=360,sc=250/2.2;
const Y=h=>base-h*sc;
const o=[];
const xs=[170,480];
o.push(...sdk.panel({id:'lane.toss',x:10,y:40,w:300,h:370,title:'Toss',state:t<=0?'At launch':(t<ta-1e-9?'Rising':(Math.abs(t-ta)<1e-9?'At the top':(t<2*ta-1e-9?'Falling':'At launch height')))}));
o.push(...sdk.panel({id:'lane.drop',x:330,y:40,w:300,h:370,title:'Drop',state:!rel?'Held in place':(t<ta+0.15?'Just released':(t<2*ta-1e-9?'Falling together':'At launch height'))}));
for(let i=0;i<2;i++){const x=xs[i]-30;o.push(sdk.line('mark'+i,x-60,Y(0),x+60,Y(0)));}
o.push(sdk.circle('ball.toss',140,Y(y),24));
o.push(sdk.circle('ball.drop',460,Y(dy),24));
if(rel)o.push(sdk.circle('ghost',460,Y(H),24,{opacity:0.25}));
o.push(...sdk.gate('gate',460,Y(H)+18,{open:rel}));
const vs=14,as=7;
o.push(...sdk.vector('vec.v.toss',{x:110,y:Y(y)},{value:tv,direction:'up'},{scale:vs,label:'v'}));
o.push(...sdk.vector('vec.a.toss',{x:170,y:Y(y)},{value:-g,direction:'up'},{scale:as,label:'a',role:'warning'}));
o.push(...sdk.vector('vec.v.drop',{x:430,y:Y(dy)},{value:dv,direction:'up'},{scale:vs,label:'v'}));
o.push(...sdk.vector('vec.a.drop',{x:490,y:Y(dy)},{value:da,direction:'up'},{scale:as,label:'a',role:'warning'}));
o.push(...sdk.callout(200,70,['v '+sdk.format(tv,2)+' m/s','a '+sdk.format(-g,1)+' m/s^2'],{id:'callout.toss'}));
o.push(...sdk.callout(520,70,['v '+sdk.format(dv,2)+' m/s','a '+sdk.format(da,1)+' m/s^2'],{id:'callout.drop'}));
return {frame:{width:640,height:420,objects:o,readouts:[{id:'tossedVelocity',value:tv},{id:'tossedAcceleration',value:-g},{id:'dropVelocity',value:dv},{id:'dropAcceleration',value:da}]},quantities:{launchSpeed:u,gravity:g,apexTime:ta,apexHeight:H,tossedVelocity:tv,tossedAcceleration:-g,tossedHeight:y,dropVelocity:dv,dropAcceleration:da,dropHeight:dy}};}
